-- Generated by scripts/schema-drift.mjs --emit (SQL-only tenant foreign keys excluded). Review before committing.
-- Tenant deletion tombstones (ch. 41 POST /tenants/current/deletion-requests). Deliberately NOT
-- tenant-owned: no FK to tenants (the row must survive the cascade that removes the tenant) and no
-- RLS. Holds no personal data — tenant id, HMAC of the slug, deletion job id, timestamps, counts.
CREATE TABLE "tenant_tombstones" (
    "tenant_id" UUID NOT NULL,
    "slug_hash" TEXT NOT NULL,
    "deletion_job_id" UUID NOT NULL,
    "started_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ(3),
    "completed_at" TIMESTAMPTZ(3),
    "counts" JSONB NOT NULL DEFAULT '{}',

    CONSTRAINT "tenant_tombstones_pkey" PRIMARY KEY ("tenant_id")
);

CREATE INDEX "tenant_tombstones_completed_at_idx" ON "tenant_tombstones"("completed_at");

-- The application role records and advances tombstones but can never remove one.
REVOKE DELETE, TRUNCATE ON TABLE "tenant_tombstones" FROM talkivio_app_role;
